export class CompanyManager{constructor(s){this.save=s;this.cash=10000;this.reputation=5;this.name="My Startup";this.stage="idea";this.users=0;const d=s.load()?.company;if(d)Object.assign(this,d)}addCash(n){this.cash+=n}addReputation(n){this.reputation+=n}setStage(s){this.stage=s}getData(){return{cash:this.cash,reputation:this.reputation,name:this.name,stage:this.stage,users:this.users}}}
